from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r in (0,h-1) or c in (0,w-1)) and grid[r][c] == 0:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    inside={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in seen}
    components=[]
    while inside:
        start=inside.pop(); comp={start}; q=deque([start])
        while q:
            r,c=q.popleft()
            for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr,nc) in inside:
                    inside.remove((nr,nc)); comp.add((nr,nc)); q.append((nr,nc))
        components.append(comp)
    out=[row[:] for row in grid]
    for comp in components:
        width=max(c for r,c in comp)-min(c for r,c in comp)+1
        color=24//width
        for r,c in comp: out[r][c]=color
    return out
